const {wilayas} = require('./data');

function getAllWilayas() {
  return wilayas;
}

function getWilayaByCode(code) {
  return wilayas.find(wilaya => wilaya.code === code);
}
function getWilayasByRegion(region) {
  return wilayas.filter(wilaya => wilaya.region.toLowerCase() === region.toLowerCase());
}

function getWilayaByName(name) {
  return wilayas.find(wilaya => wilaya.name.toLowerCase() === name.toLowerCase());
}

function getWilayaByArName(ar_name) {
  return wilayas.find(wilaya => wilaya.ar_name === ar_name);
}

function getWilayaByCapital(capital) {
  return wilayas.find(wilaya => wilaya.capital.toLowerCase() === capital.toLowerCase());
}

function getWilayaByPostalCode(codePostal) {
  return wilayas.find(wilaya => wilaya.codePostal === codePostal);
}

function checkCodePostalWilayaMatch(code, codePostal) {
    const wilaya = getWilayaByCode(code);
    return wilaya && wilaya.codePostal === codePostal;
}

function validateWilayaCode(code) {
    if (!code) return false;

    const codeStr = String(code).padStart(2, '0');

    if (!/^\d{2}$/.test(codeStr)) return false;

    return wilayas.some(wilaya => wilaya.code === codeStr);
}



module.exports = {
    getAllWilayas,
    getWilayaByCode,
    getWilayasByRegion,
    getWilayaByName,
    getWilayaByArName,
    getWilayaByCapital,
    getWilayaByPostalCode,
    checkCodePostalWilayaMatch,
    validateWilayaCode,
};





